def upgrade() -> None:
    op.execute((SQL_DIR / "05_prelude.sql").read_text())
    op.execute((SQL_DIR / "01_schema.sql").read_text())


def downgrade() -> None:
    # One table per statement outside the migration transaction: dropping ~220 tables and
    # their ~900 indexes in a single transaction exceeds max_locks_per_transaction.
    with op.get_context().autocommit_block():
        for schema, table in reversed(TABLES):
            op.execute(f"DROP TABLE IF EXISTS {schema}.{table} CASCADE")
        op.execute("DROP FUNCTION IF EXISTS shri_npi_valid(text)")
        # Schemas themselves (clinical/admin/audit) are created by sql/00_extensions.sql, run
        # once before `alembic upgrade head` - same as the extensions and roles it creates,
        # they're outside migration lifecycle and this downgrade doesn't undo them.
